entries[343719] = { ["name"] = "Steinkopfs bester Kumpel", ["text"] = "Sofort\nCa. 4 Procs pro Minute\nReagenzien:\nArmreif des besten Kumpels von Steinkopf\nNach Erhalt: Erlangt den Status des besten Kumpels. Bei weniger als 50% Gesundheit habt Ihr eine Chance, Steinkopfs zweitbeste Kumpels zu Hilfe zu rufen.\n(10s Abklingzeit)" }
entries[343720] = { ["name"] = "Bote der Demut", ["text"] = "Sofort\nIncreases the caster's attack speed by 150% for bis Abbruch.\nIncreases the movement speed of the caster by 150% for bis Abbruch.\nCauses the caster to inflict 500% increased Physical damage." }
entries[343721] = { ["name"] = "Letzte Abrechnung", ["text"] = "30 Meter Reichweite\nSofort 1 min Abklingzeit\nRuft eine Explosion himmlischer Energie herab, die allen Zielen im Zielbereich (505.312% der Angriffskraft) Heiligschaden zufügt und sie 12 Sek. lang 30% mehr Schaden durch Eure Heilige Kraft verbrauchenden Einzelzielfähigkeiten und 15% mehr Schaden durch sonstige Heilige Kraft verbrauchende Fähigkeiten erleiden lässt.\n\n[ Göttliche Hilfstruppe : Erzeugt 3 Heilige Kraft. ]" }
entries[343722] = { ["name"] = "Zermalmender Biss", ["text"] = "Nahkampfreichweite\nWirken in 2 sek.\nInflicts 6 Shadow damage to an enemy.\nInflicts 1 Shadow damage to an enemy every 3 sec for 12 Sek.." }
entries[343723] = { ["name"] = "Letzte Abrechnung", ["text"] = "Ca. 5 Procs pro Minute\nWährend diese Fähigkeit nicht von ihrer Abklingzeit betroffen ist, haben Eure Angriffe eine hohe Chance, einen Blitz herabzurufen, der (50% der Angriffskraft) Heiligschaden verursacht und das Ziel 10% mehr Schaden durch Eure nächste Heilige Kraft verbrauchende Fähigkeit erleiden lässt." }
