entries[344174] = { ["name"] = "Blitzschlagschild", ["text"] = "10 Meter Reichweite\nSofort\nElementar\nUmgibt Euch 1 Stunde lang mit einem Blitzschild.\n\nEs besteht eine Chance von 100%, dass Nahkampfangreifer (21.75% der Zaubermacht) Naturschaden erleiden, und eine Chance von 100%, dass sie 5 Mahlstrom erzeugen.\n\nEs kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n\nVerstärkung\nUmgibt Euch 1 Stunde lang mit einem Blitzschild.\n\nEs besteht eine Chance von 100%, dass Nahkampfangreifer (21.75% der Zaubermacht) Naturschaden erleiden, und eine Chance von 50%, dass sie einen Stapel von 'Waffe des Mahlstroms' erzeugen.\n\nEs kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n\nWiederherstellung\nUmgibt Euch 1 Stunde lang mit einem Blitzschild.\n\nEs besteht eine Chance von 100%, dass Nahkampfangreifer (21.75% der Zaubermacht) Naturschaden erleiden.\n\nEs kann immer nur ein Elementarschild auf dem Schamanen aktiv sein." }
