entries[344179] = { ["name"] = "Waffe des Mahlstroms", ["text"] = "Sofort\nWenn Ihr mit einer Nahkampfwaffe Schaden verursacht, besteht eine Chance, dass Ihr 'Waffe des Mahlstroms' erhaltet, was bis zu 5-mal stapelbar ist. Jeder Stapel von 'Waffe des Mahlstroms' verringert die Zauberzeit Eures nächsten Schadens- oder Heilzaubers um 20% [ Verbesserte Waffe des Mahlstroms : und erhöht dessen Schaden um 0% oder dessen Heilung um 0% ].\n\nEs können maximal 5 Stapel von 'Waffe des Mahlstroms' auf einmal aufgebraucht werden." }
