entries[344574] = { ["name"] = "Knolliger Nekrorochen", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Nekrorochen von Maldraxxus tummeln sich bevorzugt in der Nähe der riesigen, verfaulenden Pilze der Region.\"\nBeute:\nSchleimiges Nekrorochenei" }
