entries[344577] = { ["name"] = "Gebundener Schemenhund", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser Schemenhund wurde durch die Entschlüsselung und Durchführung mächtiger Runenmagie erschaffen und ist an seinen Schöpfer gebunden.\"\nQuest:\nWilder Schemenhund\nZone:\nDer Schlund" }
